SELECT df.facility_number,df.commitment,COALESCE(SUM(dd.principal),0) AS drawn,df.commitment-COALESCE(SUM(dd.principal),0) AS availability FROM debt_facility df LEFT JOIN debt_draw dd ON dd.facility_id=df.id AND dd.generation_run_id IN (:actual_run_id,:generation_run_id) WHERE df.generation_run_id IN (:actual_run_id,:generation_run_id) GROUP BY df.id,df.facility_number,df.commitment;
